def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    if not nums:
        return 0
    dp = []  # dp[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
