def solve(tokens):
    """Evaluate an expression in Reverse Polish notation.
    Tokens are strings: integers or '+', '-', '*', '/'.
    Division truncates toward zero.
    """
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division
                # Use int(a / b) to truncate toward zero for both signs
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[-1] if stack else 0

